/**
 * Creates the canonical customer, primary contact, owner service property, and exactly one scheduled job from an accepted immutable service snapshot. Idempotency-Key is required.
 * @summary Atomically create a customer and accepted initial scheduled job
 */
export const createCustomerWithInitialJobHeaderIdempotencyKeyMax = 255;

export const CreateCustomerWithInitialJobHeader = zod.object({
  "Idempotency-Key": zod
    .string()
    .max(createCustomerWithInitialJobHeaderIdempotencyKeyMax),
});

export const createCustomerWithInitialJobBodyOneOverrideReasonMax = 500;

export const createCustomerWithInitialJobBodyTwoInitialJobScheduledDateRegExp =
  new RegExp("^[0-9]{4}-[0-9]{2}-[0-9]{2}$");
export const createCustomerWithInitialJobBodyTwoInitialJobScheduledStartTimeRegExp =
  new RegExp("^([01][0-9]|2[0-3]):[0-5][0-9]$");
export const createCustomerWithInitialJobBodyTwoInitialJobScheduledEndTimeRegExp =
  new RegExp("^([01][0-9]|2[0-3]):[0-5][0-9]$");

export const createCustomerWithInitialJobBodyTwoInitialJobServiceSnapshotItemQuantityExclusiveMin = 0;

export const createCustomerWithInitialJobBodyTwoInitialJobServiceSnapshotItemUnitPriceMin = 0;

export const createCustomerWithInitialJobBodyTwoInitialJobServiceSnapshotItemTotalPriceMin = 0;

export const CreateCustomerWithInitialJobBody = zod
  .object({
    firstName: zod.string(),
    lastName: zod.string(),
    email: zod.string().nullish(),
    phone: zod.string().nullish(),
    alternatePhone: zod.string().nullish(),
    billingAddress: zod.string().nullish(),
    billingCity: zod.string().nullish(),
    billingState: zod.string().nullish(),
    billingZip: zod.string().nullish(),
    source: zod.string().nullish(),
    tags: zod.string().nullish(),
    notes: zod.string().nullish(),
    status: zod.string().optional(),
    lifecycleStatus: zod
      .enum(["prospect", "customer", "inactive", "archived"])
      .optional(),
    clientType: zod.string().optional(),
    accountType: zod.enum(["residential", "commercial"]).optional(),
    preferredContactMethod: zod.string().nullish(),
    taxExempt: zod.boolean().optional(),
    existingCustomerId: zod
      .number()
      .min(1)
      .optional()
      .describe(
        "Explicitly select an eligible strong-match account without creating a duplicate.",
      ),
    createSeparateAccount: zod
      .boolean()
      .optional()
      .describe(
        "Explicitly confirm creating a separate account when strong candidates exist.",
      ),
    overrideReason: zod
      .string()
      .max(createCustomerWithInitialJobBodyOneOverrideReasonMax)
      .optional()
      .describe(
        "Required when createSeparateAccount is true and strong candidates exist.",
      ),
  })
  .and(
    zod.object({
      billingAddress: zod.string().min(1),
      billingCity: zod.string().min(1),
      billingState: zod.string().min(1),
      billingZip: zod.string().min(1),
      initialJob: zod.object({
        accepted: zod.boolean(),
        scheduledDate: zod
          .string()
          .regex(
            createCustomerWithInitialJobBodyTwoInitialJobScheduledDateRegExp,
          ),
        scheduledStartTime: zod
          .string()
          .regex(
            createCustomerWithInitialJobBodyTwoInitialJobScheduledStartTimeRegExp,
          ),
        scheduledEndTime: zod
          .string()
          .regex(
            createCustomerWithInitialJobBodyTwoInitialJobScheduledEndTimeRegExp,
          ),
        crewId: zod.number().min(1),
        employeeIds: zod.array(zod.string().min(1)).min(1),
        notes: zod.string().nullish(),
        serviceSnapshot: zod
          .array(
            zod.object({
              serviceId: zod.number().min(1),
              serviceName: zod.string().min(1),
              description: zod.string().nullish(),
              quantity: zod
                .number()
                .gt(
                  createCustomerWithInitialJobBodyTwoInitialJobServiceSnapshotItemQuantityExclusiveMin,
                ),
              unitPrice: zod
                .number()
                .min(
                  createCustomerWithInitialJobBodyTwoInitialJobServiceSnapshotItemUnitPriceMin,
                ),
              totalPrice: zod
                .number()
                .min(
                  createCustomerWithInitialJobBodyTwoInitialJobServiceSnapshotItemTotalPriceMin,
                ),
            }),
          )
          .min(1),
      }),
    }),
  );

