export const ListEstimateAppointmentsQueryParams = zod.object({
  from: zod.date().optional(),
  to: zod.date().optional(),
  employeeId: zod.coerce.string().optional(),
});

export const ListEstimateAppointmentsResponseItem = zod.record(
  zod.string(),
  zod.unknown(),
);
export const ListEstimateAppointmentsResponse = zod.array(
  ListEstimateAppointmentsResponseItem,
);

export const ListEstimateEmployeesResponseItem = zod.object({
  id: zod.string(),
  displayName: zod.string(),
  role: zod.string(),
});
export const ListEstimateEmployeesResponse = zod.array(
  ListEstimateEmployeesResponseItem,
);

export const ListEstimateFollowUpResponseItem = zod.record(
  zod.string(),
  zod.unknown(),
);
export const ListEstimateFollowUpResponse = zod.array(
  ListEstimateFollowUpResponseItem,
);

export const getPublicEstimatePathTokenMin = 40;

export const GetPublicEstimateParams = zod.object({
  token: zod.coerce.string().min(getPublicEstimatePathTokenMin),
});

export const recordPublicEstimateActivityPathTokenMin = 40;

export const RecordPublicEstimateActivityParams = zod.object({
  token: zod.coerce.string().min(recordPublicEstimateActivityPathTokenMin),
});

export const recordPublicEstimateActivityBodyMessageMax = 1000;

export const RecordPublicEstimateActivityBody = zod.object({
  activityType: zod.enum(["downloaded", "printed", "question_requested"]),
  message: zod
    .string()
    .max(recordPublicEstimateActivityBodyMessageMax)
    .optional(),
});

export const decidePublicEstimatePathTokenMin = 40;

export const DecidePublicEstimateParams = zod.object({
  token: zod.coerce.string().min(decidePublicEstimatePathTokenMin),
});

export const decidePublicEstimateBodyDeclineReasonMax = 2000;

export const decidePublicEstimateBodyFollowUpRequestedDefault = false;

export const DecidePublicEstimateBody = zod.object({
  decision: zod.enum(["accepted", "declined"]),
  declineReason: zod
    .string()
    .max(decidePublicEstimateBodyDeclineReasonMax)
    .nullish(),
  followUpRequested: zod
    .boolean()
    .default(decidePublicEstimateBodyFollowUpRequestedDefault),
});
